mapper.select:
SELECT ORDERID ,productid ,categoryid ,pnm ,title ,cont ,qty ,price ,subtot ,TOTPRICE ,USRNO ,usrnm ,RDATE ,row_num FROM( SELECT o.ORDERID ,oi.productid ,p.categoryid ,p.pnm ,p.title ,DBMS_LOB.SUBSTR(p.cont, 200, 1) as cont ,oi.qty ,oi.price ,oi.price * oi.qty subtot ,o.TOTPRICE ,o.USRNO ,u.usrnm ,o.RDATE ,ROW_NUMBER() OVER(ORDER BY o.ORDERID desc) AS row_num FROM p_order o JOIN p_order_items oi ON o.orderid = oi.orderid JOIN products p ON p.productid = oi.productid JOIN P_CATEGORY c ON p.categoryid = c.categoryid JOIN USERS u ON u.USRNO = o.USRNO
1=1 AND o.delyn = 'N' AND u.usrno = #{usrno}
AND p.pnm like '%'|| #{searchValue} ||'%'
AND c.categorynm like '%'|| #{searchValue} ||'%'
) mypage_list_view WHERE row_num BETWEEN #{begin} AND #{end}

